import collections

# Extract all (file, line) pairs for unused imports
pattern = r'"path":"(c:\\\\[^"]+)","message":"The import [^"]+ is never used".*?"startLine":(\d+)'
matches = re.findall(pattern, text)

# Group by file
files_to_fix = collections.defaultdict(set)
for file_path, line_str in matches:
    # fix escaping
    real_path = file_path.replace(r'\\', '\\')
    files_to_fix[real_path].add(int(line_str))

count = 0
for file_path, lines in files_to_fix.items():
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            content_lines = f.readlines()
        
        # We need to sort lines descending to delete safely by index
        new_lines = []
        for i, line in enumerate(content_lines):
            # i is 0-indexed, lines is 1-indexed
            if (i + 1) not in lines:
                new_lines.append(line)
            else:
                # Double check it is actually an import line
                if line.strip().startswith('import '):
                    count += 1
                else:
                    new_lines.append(line)
        
        with open(file_path, 'w', encoding='utf-8') as f:
            f.writelines(new_lines)
    except Exception as e:
        print(f"Error processing {file_path}: {e}")

print(f"Removed {count} unused import lines based on the truncated output.")
